func getMaxBlobsPerBlock(cfg: RuntimeConfig, slot: Slot): uint64 =
  let epoch = slot.epoch
  if epoch >= cfg.FULU_FORK_EPOCH:
    get_blob_parameters(cfg, epoch).MAX_BLOBS_PER_BLOCK
  elif epoch >= cfg.ELECTRA_FORK_EPOCH:
    cfg.MAX_BLOBS_PER_BLOCK_ELECTRA
  else:
    cfg.MAX_BLOBS_PER_BLOCK

debugGloasComment ""

# Verify timestamp
if not (payload.timestamp == compute_timestamp_at_slot(state, state.slot)):
  return err("process_execution_payload: invalid timestamp")

# Verify commitments are under limit
let blob_params =
  cfg.get_blob_parameters(get_current_epoch(state))
if not (lenu64(body.blob_kzg_commitments) <= blob_params.MAX_BLOBS_PER_BLOCK):
  return err("process_execution_payload: too many KZG commitments")

